# Verb Forms, part A (DLI Grammar Reference Book I L42; II L84–91): imperative, conditional, past passive participles.
from kit import *

SRC = "From the DLI Grammar Reference Book"

SECTIONS = [

SEC("f1-imperative", "The imperative: читай, пусть, давайте", sub="DLI Lessons 42, 84 · -й, -и, -ь · -ся · irregular forms · пусть · давайте · infinitive commands", blocks=[
  P("The imperative may be formed from both the imperfective and the perfective verbs. It is formed from the 3rd person plural of the present tense or the perfective future by dropping the ending (-ют, -ут, -ят, -ат) and adding the endings of the imperative:"),
  T(["After a vowel", "After a single consonant, 1st pers. sing. stressed", "After a single consonant, 1st pers. sing. not stressed"], [
    ["-й(те)", "-и(те)", "-ь(те)"], ["Они читают — читай, читайте", "Они пишут (пишу́) — пиши, пишите", "Они бросят (бро́шу) — брось, бросьте"],
  ], row_heads=False),
  P("Notes. 1. After two or more consonants the imperative has always the ending -и(те) regardless of the stress: смотрите, помните. 2. Verbs ending in -ся follow the same rules, but the ending -ся (after -й or -ь) or -сь (after -и or -те) should be added: брей — брейся — брейтесь; готовь — готовься — готовьтесь; учи — учись — учитесь. 3. Imperfective verbs of the type of давать, вставать, which drop the suffix «ва» in the present tense, restore it in the imperative: давайте, вставайте. The imperative from есть is ешьте; from пить — пейте; from бить — бейте; from быть — будьте; from лечь — лягте (mostly replaced by ложись — ложитесь)."),
  EX(("Будьте там в 9 часов утра.", ""), ("Будьте добры купить для меня 5 марок.", "Be so kind as to buy me 5 stamps.")),
  H("Third person: пусть"),
  P("The English expressions \"let (have) him (her, them) do it\" are rendered in Russian by «пусть (пускай)» with the present imperfective or the future perfective:"),
  EX(("Пусть он пишет письмо.", "Let him write the letter."), ("Пусть они едут туда.", "Let them go there.")),
  H("First person plural: Let's…"),
  P("Constructions of the type \"Let's do it\" are rendered by давайте + infinitive of the imperfective, or давайте + perfective future. In affirmative imperfective constructions «будем» is usually omitted: *Давайте (будем) разговаривать!* In the perfective aspect the word «давайте» may be omitted, the particle -те may be added: *Давайте пойдём в кино! Пойдём в кино! Пойдёмте в кино!* \"Actual\" verbs of motion such as идти, ехать, бежать, нести, although imperfective, have imperatives of this last type: идёмте, едемте, бежимте, несёмте."),
  H("Infinitive as a command, and the negative imperative"),
  P("The infinitive in place of the imperative is used: 1. In case of urgency: *Послать за доктором!* 2. As a military command: *Открыть огонь!* 3. As a harsh or abrupt form of an order: *Встать!* The negative imperative is, as a rule, in the imperfective aspect: *Берите! Возьмите! — Не берите!* The negative imperative in the perfective aspect has the meaning of a strict warning: *Не забудьте взять ключ! Здесь скользко, не упадите!*"),
  NOTE("DLI, Lessons 42 and 84."),
], exercises=[
  FILL("Они читают → ___ ! (ты)", ["читай"], SRC + ", Lesson 84."),
  FILL("Они пишут → ___ ! (вы)", ["пишите"], "1st pers. sing. пишу́ is stressed: -и(те). " + SRC + ", Lesson 84."),
  FILL("Они бросят → ___ ! (ты)", ["брось"], "1st pers. sing. бро́шу is not stressed: -ь(те). " + SRC + ", Lesson 84."),
  MC("Они помнят → (вы)", ["помньте", "помните"], 1, "After two or more consonants always -и(те). " + SRC + ", Lesson 84."),
  FILL("готовиться → ___ ! (вы)", ["готовьтесь"], SRC + ", Lesson 84."),
  FILL("учиться → ___ ! (ты)", ["учись"], SRC + ", Lesson 84."),
  MC("давать → (вы)", ["дайте", "давайте", "даёте"], 1, "Verbs of the давать type restore -ва- in the imperative. " + SRC + ", Lesson 84."),
  FILL("пить → ___ ! (вы)", ["пейте"], SRC + ", Lesson 84."),
  FILL("___ там в 9 часов утра. (быть)", ["Будьте"], SRC + ", Lesson 84."),
  FILL("___ он пишет письмо. — Let him write the letter.", ["Пусть", "Пускай"], SRC + ", Lesson 84."),
  FILL("___ пойдём в кино! — Let's go to the movies!", ["Давайте"], SRC + ", Lesson 84."),
  MC("Let's talk!", ["Давайте разговаривать!", "Давайте разговариваем!"], 0, "«будем» is usually omitted and давайте is followed by the infinitive. " + SRC + ", Lesson 84."),
  FILL("___ огонь! (открыть — military command)", ["Открыть"], SRC + ", Lesson 84."),
  MC("Возьмите! — negative:", ["Не возьмите!", "Не берите!"], 1, "The negative imperative is, as a rule, imperfective. " + SRC + ", Lesson 84."),
  FILL("Не ___ взять ключ! (забыть — warning)", ["забудьте"], "The negative perfective imperative has the meaning of warning. " + SRC + ", Lesson 42."),
]),

SEC("f2-conditional", "If and would: бы", sub="DLI Lessons 90–91 · если and если бы · wishes · requests · ли", blocks=[
  H("First type: «если» clauses"),
  EX(("Я пойду в школу завтра, если я буду здоров.", "I'll go to school tomorrow if I am well."), ("Он работает в библиотеке, если библиотека открыта сегодня.", "He is working in the library if the library is open today.")),
  P("A sentence involving such a clause states that an event will take place if the condition is fulfilled. Being statements of direct fact, they are expressed by the indicative mood. The future condition is expressed in English by the present tense, whereas in Russian it is expressed by the future."),
  H("Second type: «если бы» clauses"),
  P("In sentences of this type the conditions postulated by the «если бы» clause are either improbable or downright contrary to existing fact. *Если бы я был здоров, я пошёл бы в школу.* — 1) If I were well, I would go to school tomorrow. 2) If I had been well, I would have gone to school yesterday. The English language uses special forms of the verb for each of these two types of supposition, whereas the Russian language, making no grammatical distinction between them, uses one form which may express either type, depending on the context."),
  P("Formation: a) Main clause: past tense of the verb with the particle «бы» following the predicate, or (rarely) the subject. b) Subordinate clause: begins with «если бы (б)», the verb being in the past tense. *Если бы он знал это, он завтра же поехал бы туда.*"),
  P("Caution: Not every English construction with \"would\" expresses the conditional mood. \"Would\" may also denote the \"future-in-the-past\". The Russian equivalent for such constructions is the future tense: *Он сказал, что он придёт позже.* — He said he would come later."),
  H("Without если бы; wishes"),
  EX(("Я пошёл бы в кино, но у меня нет времени.", ""), ("Он помог бы вам, но вы его не позвали.", ""), ("Если бы он был здесь!", "If only he were here!"), ("Если бы не вы, мы всё ещё искали бы квартиру.", "But for you we would still be looking for an apartment.")),
  H("Other uses"),
  EX(("Посидели бы у нас ещё немного!", "request, mild remonstration"), ("Вы бы купили сыну велосипед!", "= Советую вам купить сыну велосипед"), ("Ты бы перестал курить!", "= Тебе надо перестать курить"), ("Я хотел бы попросить вашего совета.", "I would like to ask your advice."), ("Скорее бы пришла пятница!", "Oh, that Friday would come soon!"), ("Выпить бы сейчас горячего чаю!", "infinitive + бы: a wish")),
  H("«ли» = whether"),
  P("The English \"if\", equivalent of \"whether\", has the Russian equivalent ЛИ. The particle ЛИ never begins the clause; it takes the second place following the word to which the question or doubt refers: *Спроси его, говорит ли он по-немецки. Я не знаю, сделают ли они это.* But: *Мы дадим ему работу, если он говорит по-немецки.*"),
  NOTE("DLI, Lessons 90 and 91."),
], exercises=[
  MC("I'll go to school tomorrow if I am well. — …если я ___ здоров.", ["был", "буду", "есть"], 1, "The future condition is expressed in Russian by the future. " + SRC + ", Lesson 90."),
  FILL("Если ___ я был здоров, я пошёл бы в школу.", ["бы"], SRC + ", Lesson 90."),
  MC("Если бы он знал это, он завтра же ___ туда.", ["поедет бы", "поехал бы", "поехать бы"], 1, "Main clause: past tense + бы. " + SRC + ", Lesson 90."),
  MC("He said he would come later.", ["Он сказал, что он пришёл бы позже.", "Он сказал, что он придёт позже."], 1, "Future-in-the-past: the Russian future tense. " + SRC + ", Lesson 90."),
  FILL("Я ___ бы в кино, но у меня нет времени. (пойти)", ["пошёл", "пошел"], SRC + ", Lesson 90."),
  FILL("Если бы он ___ здесь! (быть)", ["был"], SRC + ", Lesson 90."),
  FILL("Я ___ бы попросить вашего совета. (хотеть)", ["хотел"], SRC + ", Lesson 90."),
  FILL("___ бы сейчас горячего чаю! (выпить)", ["Выпить"], SRC + ", Lesson 90."),
  FILL("Если бы не ___, мы всё ещё искали бы квартиру. — But for you…", ["вы"], SRC + ", Lesson 91."),
  MC("Ask him if he speaks German.", ["Спроси его, если он говорит по-немецки.", "Спроси его, говорит ли он по-немецки."], 1, SRC + ", Lesson 91."),
  FILL("Я не знаю, сделают ___ они это.", ["ли"], SRC + ", Lesson 91."),
]),

SEC("f3-short-passive", "Short past passive participles: куплен, написан, открыт", sub="DLI Lessons 85–87 · -ен/-ён · -н · -т · быть + PPP · English passives", blocks=[
  P("If the verb of a sentence is transitive, the idea may be expressed in two ways: if we want to emphasize the performer of the action, we use the active voice; if we want to emphasize the object or target of the action, we express the same thought in the passive. *Студент купил книгу. — Книга куплена студентом.* In the passive construction the performer of the action is expressed by the instrumental case (студентом)."),
  P("The new relations are expressed in Russian by a special form of the verb which is called the short past passive participle (PPP). It is used only as a predicate in passive constructions. Past passive participles express the idea of a completed action and are almost exclusively formed from perfective transitive verbs."),
  H("Group 1: verbs in -ить and -ти"),
  P("They form the short PPP from the first person singular future perfective by dropping the ending -у or -ю and adding -ен, -ена, -ено, -ены (stressed: -ён, -ена́, -ено́, -ены́): куплю — куплен, куплена, куплено, куплены; приведён, приведена, приведено, приведены. In most verbs the stress remains on the same syllable as in the 2nd person singular: бросишь — брошен; предложишь — предложен; принесёшь — принесён; but: изменишь — изменён. The changes of consonants of the future also appear: спрошу — спрошен; замечу — замечен; отпущу — отпущен; посажу — посажен; куплю — куплен; возвращу — возвращён; приглашу — приглашён."),
  H("Group 2: verbs in -ать, -ять, -еть"),
  P("They form the short PPP from the masculine past tense by dropping -л and adding -н, -на, -но, -ны: сделал — сделан; потерял — потерян; осмотрел — осмотрен. The stress shifts one syllable to the left if in the infinitive it is on the last syllable: написать — написан; связать — связан; осмотреть — осмотрен; and remains unchanged in all other cases: услышан, сделан."),
  H("Group 3: the suffix -т"),
  P("a) Prefixed derivatives from some monosyllabic verbs: убит, разбит, открыт, закрыт, покрыт, скрыт, помыт, побрит. b) Verbs in -нять: понят, снят, занят, принят. c) Verbs in -нуть: вынут, повёрнут. d) Verbs in -деть: надет, одет, раздет. e) забыт, начат, взят. The PPP from съесть is съеден. The verb «вернуть» has no PPP; it is formed from «возвратить»: возвращён."),
  H("Short PPPs and short adjectives"),
  T(["Short adjectives", "Short PPP"], [["Он свободен.", "Дом куплен."], ["Она свободна.", "Книга куплена."], ["Оно свободно.", "Вино куплено."], ["Они свободны.", "Столы куплены."]], row_heads=False),
  P("Both are used as predicates only; both are not declined; both agree in gender and number with the subject. To express tense the verb быть is used exactly as with short adjectives:"),
  EX(("Гараж построен.", "The garage is (has been) built."), ("Гараж был построен в 1950 году.", "The garage was built in 1950."), ("Гараж будет построен через год.", "The garage will be built in a year."), ("Школа должна быть построена.", "The school must be built."), ("Книга могла быть взята вчера.", "The book may have been taken yesterday.")),
  H("English and Russian passives"),
  P("For each set of two parallel English constructions there is only one in Russian: The letter is written / has been written — *Письмо написано.* The letter was written / had been written — *Письмо было написано.* Passive constructions with the indirect object as subject are impossible in Russian: I was given a book — *Мне дали книгу. Мне была дана книга.* Verbs that take a preposition, or are intransitive in Russian, can only be translated actively: *Над ним смеялись. За доктором послали. Ему помогли друзья.*"),
  NOTE("DLI, Lessons 85–87."),
], exercises=[
  FILL("Студент купил книгу. → Книга ___ студентом.", ["куплена"], SRC + ", Lesson 85."),
  FILL("Книга куплена ___ . (студент)", ["студентом"], "The performer of the action is in the instrumental case. " + SRC + ", Lesson 85."),
  FILL("бросить → он ___", ["брошен"], SRC + ", Lesson 85."),
  MC("принести → он", ["принесен", "принесён", "принёсен"], 1, SRC + ", Lesson 85."),
  FILL("спросить → он ___", ["спрошен"], "The consonant change of the future (спрошу) appears in the PPP. " + SRC + ", Lesson 85."),
  FILL("пригласить → он ___", ["приглашён", "приглашен"], SRC + ", Lesson 85."),
  FILL("сделать → оно ___", ["сделано"], SRC + ", Lesson 86."),
  MC("написать → он", ["написан", "написен", "написат"], 0, SRC + ", Lesson 86."),
  FILL("потерять → она ___", ["потеряна"], SRC + ", Lesson 86."),
  MC("открыть → он", ["открын", "открыт", "открен"], 1, "Prefixed derivatives of monosyllabic verbs take -т. " + SRC + ", Lesson 86."),
  FILL("занять → она ___", ["занята"], SRC + ", Lesson 86."),
  FILL("одеть → он ___", ["одет"], SRC + ", Lesson 86."),
  FILL("начать → оно ___", ["начато"], SRC + ", Lesson 86."),
  MC("вернуть → (PPP)", ["вернут", "возвращён"], 1, "«вернуть» has no PPP; it is formed from «возвратить». " + SRC + ", Lesson 86."),
  FILL("Гараж ___ построен в 1950 году.", ["был"], SRC + ", Lesson 86."),
  FILL("Гараж ___ построен через год.", ["будет"], SRC + ", Lesson 86."),
  FILL("Школа должна ___ построена.", ["быть"], SRC + ", Lesson 86."),
  MC("I was given a book.", ["Я был дан книгу.", "Мне дали книгу."], 1, "Passives with the indirect object as subject are impossible in Russian. " + SRC + ", Lesson 87."),
  FILL("The doctor was sent for. — За ___ послали.", ["доктором"], SRC + ", Lesson 87."),
]),

SEC("f4-long-passive", "Long past passive participles: купленная книга", sub="DLI Lessons 88–89 · -нный, -тый · participial phrases · который", blocks=[
  P("Short PPP as well as short adjectives are used as predicates. Long PPP as well as long adjectives are used as noun modifiers:"),
  T(["", "Adjectives", "PPP"], [["Short", "Этот стул свободен.", "Обед заказан."], ["Long", "Я сел на свободный стул.", "Я заплатил за заказанный обед."]]),
  H("Formation"),
  P("The long form of the PPP is obtained from its short masculine form by adding: 1. -н + -ый (-ая, -ое, -ые) to the PPP ending in -н: куплен — купленный, купленная, купленное, купленные. 2. -ый (-ая, -ое, -ые) to the PPP ending in -т: убит — убитый, убитая, убитое, убитые."),
  P("Like adjectives they answer the question какой? and agree in gender, number and case with the word modified. They are declined exactly like adjectives: *Он нашёл интересную книгу. — Он нашёл потерянную книгу. Вот ящик с новыми журналами. — Вот ящик с полученными журналами.* Like verbs the long PPPs can have objects, adverbial modifiers, etc., forming participial phrases: *посланная матерью раненому сыну телеграмма.* They express the passive voice, the perfective aspect and the past tense."),
  H("The place of the long PPP"),
  P("1. If the modifier is a single participle it is always placed before the word modified: *Он принёс проверенную работу.* 2. A participial phrase is usually placed after the word modified (and must be separated from it by a comma); it may also be placed before the modified word, without a comma: *Он принёс книгу, забытую вами в библиотеке. Он принёс забытую вами в библиотеке книгу.*"),
  H("Participial phrases and «который» clauses"),
  EX(("Мы ждём даму, приглашённую моей женой.", ""), ("Мы ждём даму, которая приглашена моей женой.", ""), ("Мы ждём даму, которую моя жена пригласила.", "")),
  P("a) The long PPP always agrees with the modified word; b) «который» as subject of a passive subordinate clause is always in the nominative case; c) «который» as direct object of an active clause will always be in the accusative case."),
  T(["", "a) PPP", "b) passive", "c) active"], [
    ["Он пришёл с книгой,", "полученной его братом из Европы.", "которая получена его братом из Европы.", "которую его брат получил из Европы."],
    ["Мы говорим о книгах,", "полученных его братом из Европы.", "которые получены его братом из Европы.", "которые его брат получил из Европы."],
  ]),
  P("Clauses which cannot be replaced by long PPP: 1) clauses with intransitive verbs: *Генерал подошёл к карте, которая висела на стене.* 2) clauses in which the passive is in the future: *Мы узнали фамилию офицера, который скоро будет переведён в нашу роту.*"),
  NOTE("DLI, Lessons 88 and 89."),
], exercises=[
  FILL("куплен → ___ (masc. long form)", ["купленный"], SRC + ", Lesson 88."),
  FILL("убит → ___ (masc. long form)", ["убитый"], SRC + ", Lesson 88."),
  FILL("Я заплатил за ___ обед. (заказан)", ["заказанный"], SRC + ", Lesson 88."),
  FILL("Он нашёл ___ книгу. (потерян)", ["потерянную"], SRC + ", Lesson 88."),
  FILL("Вот ящик с ___ журналами. (получен)", ["полученными"], SRC + ", Lesson 88."),
  FILL("Он принёс ___ работу. (проверен)", ["проверенную"], SRC + ", Lesson 88."),
  FILL("Он принёс книгу, ___ вами в библиотеке. (забыт)", ["забытую"], SRC + ", Lesson 88."),
  FILL("Мы ждём даму, ___ моей женой. (приглашён)", ["приглашённую", "приглашенную"], SRC + ", Lesson 89."),
  MC("Мы ждём даму, ___ моя жена пригласила.", ["которая", "которую"], 1, "«который» as direct object of an active clause is in the accusative. " + SRC + ", Lesson 89."),
  MC("Мы ждём даму, ___ приглашена моей женой.", ["которая", "которую"], 0, "«который» as subject of a passive clause is in the nominative. " + SRC + ", Lesson 89."),
  FILL("Он пришёл с книгой, ___ его братом из Европы. (получен)", ["полученной"], SRC + ", Lesson 89."),
  FILL("Мы говорим о книгах, ___ его братом из Европы. (получен)", ["полученных"], SRC + ", Lesson 89."),
]),

]
